<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanban Board</title>
<style>
  :root {
    --bg: #f4f5f7;
    --surface: #ffffff;
    --border: #e3e6ea;
    --text: #1f2430;
    --muted: #6b7280;
    --accent: #4f6ef7;
    --shadow: 0 1px 2px rgba(16,24,40,.06), 0 4px 12px rgba(16,24,40,.06);
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 28px 24px 48px;
    background: var(--bg);
    color: var(--text);
    font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
  }
  h1 {
    margin: 0 0 4px;
    font-size: 24px;
    letter-spacing: -.02em;
  }
  .sub {
    margin: 0 0 22px;
    color: var(--muted);
    font-size: 13px;
  }
  .composer {
    display: flex;
    gap: 10px;
    margin-bottom: 26px;
    max-width: 560px;
  }
  #new-card {
    flex: 1;
    padding: 11px 14px;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: var(--surface);
    font: inherit;
    color: inherit;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }
  #new-card:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(79,110,247,.15);
  }
  #add-card {
    padding: 11px 20px;
    border: 0;
    border-radius: 10px;
    background: var(--accent);
    color: #fff;
    font: inherit;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s, transform .05s;
  }
  #add-card:hover { background: #3f5be0; }
  #add-card:active { transform: translateY(1px); }

  .board {
    display: grid;
    grid-template-columns: repeat(3, minmax(240px, 1fr));
    gap: 18px;
    align-items: start;
  }
  @media (max-width: 780px) {
    .board { grid-template-columns: 1fr; }
  }
  .column {
    background: #ecedf0;
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 14px;
    min-height: 180px;
    transition: background .15s, box-shadow .15s;
  }
  .column.drag-over {
    background: #e2e8ff;
    box-shadow: inset 0 0 0 2px var(--accent);
  }
  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
    padding: 0 2px;
  }
  .col-title {
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .07em;
    color: #464c59;
  }
  .count {
    min-width: 24px;
    height: 22px;
    padding: 0 7px;
    border-radius: 11px;
    background: #d5d8de;
    color: #3c414c;
    font-size: 12px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
  .cards {
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 60px;
  }
  .card {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 12px 12px 12px 14px;
    box-shadow: var(--shadow);
    cursor: grab;
    transition: box-shadow .15s, transform .08s, opacity .15s;
  }
  .card:hover { box-shadow: 0 2px 4px rgba(16,24,40,.08), 0 8px 20px rgba(16,24,40,.10); }
  .card:active { cursor: grabbing; }
  .card.dragging { opacity: .45; transform: rotate(1deg); }
  .card-title {
    flex: 1;
    word-break: break-word;
    white-space: pre-wrap;
  }
  .card-del {
    flex: none;
    width: 24px;
    height: 24px;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: #9aa1ad;
    font-size: 17px;
    line-height: 1;
    cursor: pointer;
    transition: background .15s, color .15s;
  }
  .card-del:hover { background: #fdeaea; color: #d9534f; }
  .empty {
    color: #9aa1ad;
    font-size: 12.5px;
    text-align: center;
    padding: 10px 0;
    border: 1px dashed #cfd3da;
    border-radius: 9px;
  }
</style>
</head>
<body>

<h1>Kanban Board</h1>
<p class="sub">Add a card, drag it between columns. Everything is saved locally.</p>

<div class="composer">
  <input id="new-card" type="text" placeholder="What needs doing?" autocomplete="off">
  <button id="add-card" type="button">Add card</button>
</div>

<div class="board">
  <section class="column" id="col-todo" data-col="todo">
    <div class="col-header">
      <span class="col-title">To Do</span>
      <span class="count">0</span>
    </div>
    <div class="cards"></div>
  </section>

  <section class="column" id="col-doing" data-col="doing">
    <div class="col-header">
      <span class="col-title">Doing</span>
      <span class="count">0</span>
    </div>
    <div class="cards"></div>
  </section>

  <section class="column" id="col-done" data-col="done">
    <div class="col-header">
      <span class="col-title">Done</span>
      <span class="count">0</span>
    </div>
    <div class="cards"></div>
  </section>
</div>

<script>
(function () {
  var STORE_KEY = 'kanban.board.v1';
  var COLS = ['todo', 'doing', 'done'];

  var input = document.getElementById('new-card');
  var addBtn = document.getElementById('add-card');
  var columns = {};
  COLS.forEach(function (id) {
    columns[id] = document.getElementById('col-' + id);
  });

  // state: [{id, title, col}]
  var state = load();
  var seq = 0;

  function load() {
    try {
      var raw = localStorage.getItem(STORE_KEY);
      if (!raw) return [];
      var data = JSON.parse(raw);
      if (!Array.isArray(data)) return [];
      return data.filter(function (c) {
        return c && typeof c.title === 'string' && COLS.indexOf(c.col) !== -1;
      }).map(function (c) {
        return { id: String(c.id || nextId()), title: c.title, col: c.col };
      });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(state));
    } catch (e) { /* storage unavailable — board still works in-session */ }
  }

  function nextId() {
    seq += 1;
    return 'c' + seq + '-' + String(Math.floor(Math.random() * 1e9));
  }

  function buildCard(card) {
    var el = document.createElement('div');
    el.className = 'card';
    el.setAttribute('draggable', 'true');
    el.dataset.id = card.id;

    var title = document.createElement('span');
    title.className = 'card-title';
    title.textContent = card.title;

    var del = document.createElement('button');
    del.className = 'card-del';
    del.type = 'button';
    del.setAttribute('aria-label', 'Delete card');
    del.textContent = '\u00d7';
    del.addEventListener('click', function (e) {
      e.stopPropagation();
      removeCard(card.id);
    });

    el.appendChild(title);
    el.appendChild(del);

    el.addEventListener('dragstart', function (e) {
      el.classList.add('dragging');
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        try { e.dataTransfer.setData('text/plain', card.id); } catch (err) {}
      }
    });
    el.addEventListener('dragend', function () {
      el.classList.remove('dragging');
      Object.keys(columns).forEach(function (k) {
        columns[k].classList.remove('drag-over');
      });
    });

    return el;
  }

  function render() {
    COLS.forEach(function (id) {
      var col = columns[id];
      var holder = col.querySelector('.cards');
      holder.textContent = '';

      var items = state.filter(function (c) { return c.col === id; });
      items.forEach(function (c) { holder.appendChild(buildCard(c)); });

      if (items.length === 0) {
        var empty = document.createElement('div');
        empty.className = 'empty';
        empty.textContent = 'Drop cards here';
        holder.appendChild(empty);
      }

      col.querySelector('.count').textContent = String(items.length);
    });
  }

  function addCard(rawTitle) {
    var title = (rawTitle || '').trim();
    if (!title) return;
    state.push({ id: nextId(), title: title, col: 'todo' });
    save();
    render();
  }

  function removeCard(id) {
    state = state.filter(function (c) { return c.id !== id; });
    save();
    render();
  }

  function moveCard(id, col) {
    if (COLS.indexOf(col) === -1) return;
    var moved = false;
    state.forEach(function (c) {
      if (c.id === id && c.col !== col) { c.col = col; moved = true; }
    });
    if (moved) { save(); render(); }
  }

  addBtn.addEventListener('click', function () {
    addCard(input.value);
    input.value = '';
    input.focus();
  });

  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      addCard(input.value);
      input.value = '';
    }
  });

  COLS.forEach(function (id) {
    var col = columns[id];

    col.addEventListener('dragover', function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
      col.classList.add('drag-over');
    });

    col.addEventListener('dragenter', function (e) {
      e.preventDefault();
      col.classList.add('drag-over');
    });

    col.addEventListener('dragleave', function (e) {
      if (!col.contains(e.relatedTarget)) col.classList.remove('drag-over');
    });

    col.addEventListener('drop', function (e) {
      e.preventDefault();
      col.classList.remove('drag-over');
      var cardId = '';
      if (e.dataTransfer) {
        try { cardId = e.dataTransfer.getData('text/plain'); } catch (err) {}
      }
      if (!cardId) {
        var dragging = document.querySelector('.card.dragging');
        if (dragging) cardId = dragging.dataset.id;
      }
      if (cardId) moveCard(cardId, id);
    });
  });

  render();
})();
</script>
</body>
</html>
